import{describe,it,expect}from"vitest";import fs from"node:fs";import path from"node:path";const IGNORED=new Set([".git","node_modules","dist","coverage"]);function htmlFiles(t,e=[]){for(const o of fs.readdirSync(t,{withFileTypes:!0})){if(IGNORED.has(o.name))continue;const s=path.join(t,o.name);o.isDirectory()?htmlFiles(s,e):o.name.endsWith(".html")&&e.push(s)}return e}const ABOVE_FOLD=/hero|banner|masthead|jumbotron|splash|cover|logo|brand/i;function lazyCandidates(t){const e=[];let o=0;for(const s of t.matchAll(/<img\b[^>]*>/gi)){const n=s[0],i=o++;if(/\sdata-src\s*=/i.test(n))continue;const a=n.match(/\ssrc\s*=\s*["']([^"']*)["']/i);if(!a||!a[1].trim())continue;if(0===i)continue;const c=t.slice(Math.max(0,s.index-400),s.index+n.length);ABOVE_FOLD.test(n)||ABOVE_FOLD.test(c)||e.push(n)}return e}describe("image lazy-loading",()=>{const t=htmlFiles(".").map(t=>({file:t,content:fs.readFileSync(t,"utf8")}));it("scans the repository",()=>{expect(t.length).toBeGreaterThan(0)}),it("marks every below-the-fold image as lazy",()=>{const e=[];for(const{file:o,content:s}of t)for(const t of lazyCandidates(s))/loading\s*=/i.test(t)||e.push(`${o}: ${t.slice(0,70)}`);expect(e).toEqual([])}),it("leaves above-the-fold images eager so they do not delay LCP",()=>{for(const{content:e}of t)for(const t of lazyCandidates(e))expect(t).not.toMatch(/\bclass\s*=\s*["'][^"']*\bhero-image\b/i)})});